(43561, 'Genesis 46:23', 'Genesis', 46, 23, 'دان او د هغه زوی حوشیم.', 'دان او د هغه زوی حوشیم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43562, 'Genesis 46:24', 'Genesis', 46, 24, 'نفتالي او د هغه زامن: یحصییل، جوني، یصر او شلیم.', 'نفتالی او د هغه زامن: یحصییل، جونی، یصر او شلیم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43563, 'Genesis 46:25', 'Genesis', 46, 25, 'دغه اووه تنه د یعقوب اولاده وه چې د بلهې څخه پیدا شوي وو او بلهه هغه وینځه وه چې لابان خپلې لور راحیل ته ورکړې وه.', 'دغه اووه تنه د یعقوب اولاده وه چې د بلهې چخه پیدا شوی وو او بلهه هغه وینجه وه چې لابان خپلې لور راحیل ته ورکرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43564, 'Genesis 46:26', 'Genesis', 46, 26, 'د هغو کسانو شمېر چې په خپله د یعقوب د نسل څخه وو او د هغه سره مصر ته تللي وو، ټول شپږشپېته تنه وو چې په هغو کې د یعقوب د زامنو ښځې شاملې نه وې.', 'د هغو کسانو شمېر چې په خپله د یعقوب د نسل چخه وو او د هغه سره مصر ته تللی وو، تول شپزشپېته تنه وو چې په هغو کې د یعقوب د زامنو شجې شاملې نه وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43565, 'Genesis 46:27', 'Genesis', 46, 27, 'د یوسف زامن چې په مصر کې پیدا شول دوه تنه وو. نو د یعقوب د کورنۍ غړي چې مصر ته تللي وو ټول اویا تنه وو.', 'د یوسف زامن چې په مصر کې پیدا شول دوه تنه وو. نو د یعقوب د کورنی غری چې مصر ته تللی وو تول اویا تنه وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43566, 'Genesis 46:28', 'Genesis', 46, 28, 'یعقوب یهودا د ځان څخه مخکې یوسف ته ولېږه چې د جوشن لاره ورته وروښایي. کله چې هغوی د جوشن سیمې ته ورسېدل،', 'یعقوب یهودا د جان چخه مخکې یوسف ته ولېزه چې د جوشن لاره ورته وروشایی. کله چې هغوی د جوشن سیمې ته ورسېدل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_28.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43567, 'Genesis 46:29', 'Genesis', 46, 29, 'یوسف خپله جنګي ګاډۍ تیاره کړه او جوشن ته د خپل پلار د لیدلو دپاره روان شو او څنګه چې یې هغه ولیده، په غېږ کې یې ونیوه او ډېر یې وژړل.', 'یوسف خپله جنګی ګادی تیاره کره او جوشن ته د خپل پلار د لیدلو دپاره روان شو او چنګه چې یې هغه ولیده، په غېز کې یې ونیوه او دېر یې وژرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43568, 'Genesis 46:30', 'Genesis', 46, 30, 'یعقوب یوسف ته وویل: «اوس زه مرګ ته تیار یم، ځکه چې ته مې ولیدلې او پوه شوم چې تر‌اوسه پورې ژوندی یې.»', 'یعقوب یوسف ته وویل: «اوس زه مرګ ته تیار یم، جکه چې ته مې ولیدلې او پوه شوم چې تر‌اوسه پورې ژوندی یې.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43569, 'Genesis 46:31', 'Genesis', 46, 31, 'نو بیا یوسف خپلو ورونو او د خپل پلار کورنۍ ته وویل: «زه ځم او د فرعون سره خبرې کوم او ورته به ووایم چې زما ورونه او زما د پلار ټوله کورنۍ چې په کنعان کې اوسېدل، ماته راغلي دي.', 'نو بیا یوسف خپلو ورونو او د خپل پلار کورنی ته وویل: «زه جم او د فرعون سره خبرې کوم او ورته به ووایم چې زما ورونه او زما د پلار توله کورنی چې په کنعان کې اوسېدل، ماته راغلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43570, 'Genesis 46:32', 'Genesis', 46, 32, 'دا خلک شپانه دي او حیوانات ساتي او خپلې رمې، پادې او هرڅه چې یې درلودل د ځان سره یې راوړي دي.', 'دا خلک شپانه دی او حیوانات ساتی او خپلې رمې، پادې او هرچه چې یې درلودل د جان سره یې راوری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43571, 'Genesis 46:33', 'Genesis', 46, 33, 'کله چې فرعون تاسو راوغواړي او پوښتنه درڅخه وکړي چې تاسو څه کسب کوئ،', 'کله چې فرعون تاسو راوغواری او پوشتنه درچخه وکری چې تاسو چه کسب کوی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43572, 'Genesis 46:34', 'Genesis', 46, 34, 'نو تاسو باید ځواب ورکړئ چې مونږ د هلکتوب څخه د خپلو نیکونو په شان تر‌اوسه پورې حیوانات ساتو. نو بیا به تاسو ته اجازه درکړي چې د جوشن په سیمه کې واوسېږئ.» یوسف دا خبره په دې خاطر وکړه چې مصریان د شپنو څخه کرکه کوي.', 'نو تاسو باید جواب ورکری چې مونز د هلکتوب چخه د خپلو نیکونو په شان تر‌اوسه پورې حیوانات ساتو. نو بیا به تاسو ته اجازه درکری چې د جوشن په سیمه کې واوسېزی.» یوسف دا خبره په دې خاطر وکره چې مصریان د شپنو چخه کرکه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_46_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43573, 'Hosea 11:1', 'Hosea', 11, 1, 'څښتن وایي: اسراییل چې کله ؤ ماشوم راباندې ګران ؤ لکه د زوی په شان او ما د مصر نه راوغوښت هغه', 'چشتن وایی: اسراییل چې کله و ماشوم راباندې ګران و لکه د زوی په شان او ما د مصر نه راوغوشت هغه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43574, 'Hosea 11:2', 'Hosea', 11, 2, 'خو څومره چې ما کاوه اواز هغه ته لېرې کېده هومره زما نه هغه بعل بتانو ته کوله قرباني زما قوم سوځولې خوشبویي هغوی بتانو ته', 'خو چومره چې ما کاوه اواز هغه ته لېرې کېده هومره زما نه هغه بعل بتانو ته کوله قربانی زما قوم سوجولې خوشبویی هغوی بتانو ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43575, 'Hosea 11:3', 'Hosea', 11, 3, 'خو بیاهم زه وم چې مې زده کړ اسراییل ته د ګرځېدلو چل هغه مې ونیوه د لاسونو څخه خو هغه پوه نه شو چې ما پام کاوه هغه باندې', 'خو بیاهم زه وم چې مې زده کر اسراییل ته د ګرجېدلو چل هغه مې ونیوه د لاسونو چخه خو هغه پوه نه شو چې ما پام کاوه هغه باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43576, 'Hosea 11:4', 'Hosea', 11, 4, 'ما د مینې او محبت په رسۍ راکش کړل هغوی خپل ځان ته ما را‌اوچت کړ جغ چې هغوی وکړي خوراک زه ورټیټ شومه هغوی ته او خواړه مې ورکړل', 'ما د مینې او محبت په رسی راکش کرل هغوی خپل جان ته ما را‌اوچت کر جغ چې هغوی وکری خوراک زه ورتیت شومه هغوی ته او خواره مې ورکرل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43577, 'Hosea 11:5', 'Hosea', 11, 5, 'هغوی باید مصر ته ورستانه نه شي، خو آشوریان به په هغوی باندې حکومت کوي، ځکه چې هغوی نه غواړي چې بېرته زما خواته راوګرځي.', 'هغوی باید مصر ته ورستانه نه شی، خو اشوریان به په هغوی باندې حکومت کوی، جکه چې هغوی نه غواری چې بېرته زما خواته راوګرجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43578, 'Hosea 11:6', 'Hosea', 11, 6, 'جنګ به لکه د توفان په شان د هغوی ښارونو ته راځي او د ښار دروازې به ماتې کړي. جنګ به زما خلک برباد کړي، ځکه چې هغوی به د خپلو بدو دسیسو له امله له منځه لاړ شي.', 'جنګ به لکه د توفان په شان د هغوی شارونو ته راجی او د شار دروازې به ماتې کری. جنګ به زما خلک برباد کری، جکه چې هغوی به د خپلو بدو دسیسو له امله له منجه لار شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43579, 'Hosea 11:7', 'Hosea', 11, 7, 'زما خلکو پرېکړه کړې ده چې د هغه خدای په خاطر ما رد کړي چې دوی فکر کوي هغه ډېر قوي دی، خو هغه مرسته نه شي کولی.', 'زما خلکو پرېکره کرې ده چې د هغه خدای په خاطر ما رد کری چې دوی فکر کوی هغه دېر قوی دی، خو هغه مرسته نه شی کولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43580, 'Hosea 11:8', 'Hosea', 11, 8, 'ای اسراییله، څنګه کولی شم چې تا پرېږدم؟ څنګه کولای شم چې دې تسلیم کړم چاته؟ کله کولای شم زه چې کړم تباه تا لکه ښار د ادمه؟ یا تا سره کار وکړم په شان د زبوییم د ښار؟ زړه مې نه غواړي چې وکړمه زه داسې کار ځکه چې ستا سره کړمه ډېره زیاته مینه', 'ای اسراییله، چنګه کولی شم چې تا پرېزدم؟ چنګه کولای شم چې دې تسلیم کرم چاته؟ کله کولای شم زه چې کرم تباه تا لکه شار د ادمه؟ یا تا سره کار وکرم په شان د زبوییم د شار؟ زره مې نه غواری چې وکرمه زه داسې کار جکه چې ستا سره کرمه دېره زیاته مینه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43581, 'Hosea 11:9', 'Hosea', 11, 9, 'د خپل سخت قهر په وخت کې به زه درنه کړم سزا زه به بیا نه کړم اسراییل تباه ځکه چې خدای یمه، انسان نه یمه سپېڅلی ذات یم او تا سره مل یمه زه زه به رانه شم په غضب تا ته', 'د خپل سخت قهر په وخت کې به زه درنه کرم سزا زه به بیا نه کرم اسراییل تباه جکه چې خدای یمه، انسان نه یمه سپېچلی ذات یم او تا سره مل یمه زه زه به رانه شم په غضب تا ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43582, 'Hosea 11:10', 'Hosea', 11, 10, 'کله چې زه په خپلو خلکو باندې لکه د زمري په شان وغورېږم، نو زما غوره شوی قوم به ولړزیږي. هغوی به زما پیروي وکړي. هغوی به په وېره د لوېدیځې خوا نه ماته راشي.', 'کله چې زه په خپلو خلکو باندې لکه د زمری په شان وغورېزم، نو زما غوره شوی قوم به ولرزیزی. هغوی به زما پیروی وکری. هغوی به په وېره د لوېدیجې خوا نه ماته راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43583, 'Hosea 11:11', 'Hosea', 11, 11, 'هغوی به له وېرې د مصر نه د مرغانو په شان والوزي او د آشور نه به د کوترو په شان راشي. هغوی به بېرته خپلو کورونو ته راولم.', 'هغوی به له وېرې د مصر نه د مرغانو په شان والوزی او د اشور نه به د کوترو په شان راشی. هغوی به بېرته خپلو کورونو ته راولم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43584, 'Hosea 11:12', 'Hosea', 11, 12, 'د اسراییلو خلک په دروغو او چل سره زما څخه راتاو شوي دي او د یهودا خلک لا تر‌اوسه پورې زما په وړاندې چې وفادار او سپېڅلی خدای یم، سرکښي کوي. ما څښتن داسې ویلي دي.', 'د اسراییلو خلک په دروغو او چل سره زما چخه راتاو شوی دی او د یهودا خلک لا تر‌اوسه پورې زما په وراندې چې وفادار او سپېچلی خدای یم، سرکشی کوی. ما چشتن داسې ویلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_11_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43585, 'Genesis 3:1', 'Genesis', 3, 1, 'د هغو ټولو وحشي حیواناتو د ډلې څخه چې څښتن خدای جوړ کړي وو، مار ډېر مکرجن ؤ. یوه ورځ هغه ښځې ته راغی او پوښتنه یې ترې وکړه: «ایا په رښتیا خدای تاسو ته ویلي دي چې په باغ کې د هېڅ یوې ونې مېوه ونه خورئ؟»', 'د هغو تولو وحشی حیواناتو د دلې چخه چې چشتن خدای جور کری وو، مار دېر مکرجن و. یوه ورج هغه شجې ته راغی او پوشتنه یې ترې وکره: «ایا په رشتیا خدای تاسو ته ویلی دی چې په باغ کې د هېچ یوې ونې مېوه ونه خوری؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43586, 'Genesis 3:2', 'Genesis', 3, 2, 'ښځې ځواب ورکړ: «خدای ویلي دي چې مونږ کولای شو د باغ د ټولو ونو د مېوو څخه وخورو،', 'شجې جواب ورکر: «خدای ویلی دی چې مونز کولای شو د باغ د تولو ونو د مېوو چخه وخورو،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43587, 'Genesis 3:3', 'Genesis', 3, 3, 'بې له هغې ونې څخه چې د باغ په منځ کې ده. هغه مونږ ته ویلي دي چې د هغې ونې مېوه مه خورئ او حتی هغې ته لاس هم مه وروړئ، که داسې مو وکړل، نو تاسو به مړه شئ.»', 'بې له هغې ونې چخه چې د باغ په منج کې ده. هغه مونز ته ویلی دی چې د هغې ونې مېوه مه خوری او حتی هغې ته لاس هم مه وروری، که داسې مو وکرل، نو تاسو به مره شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43588, 'Genesis 3:4', 'Genesis', 3, 4, 'مار ښځې ته وویل: «ډاډه اوسئ، تاسو به مړه نه شئ.', 'مار شجې ته وویل: «داده اوسی، تاسو به مره نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43589, 'Genesis 3:5', 'Genesis', 3, 5, 'خدای پوهیږي چې که چېرې تاسو د دې ونې مېوه وخورئ، نو ستاسو سترګې به خلاصې شي او تاسو به د خدای په شان شئ او په ښو او بدو شیانو باندې به پوه شئ.»', 'خدای پوهیزی چې که چېرې تاسو د دې ونې مېوه وخوری، نو ستاسو سترګې به خلاصې شی او تاسو به د خدای په شان شی او په شو او بدو شیانو باندې به پوه شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43590, 'Genesis 3:6', 'Genesis', 3, 6, 'ښځې ونې ته په ځیر وکتل او هغه ونه د هغې په نظر کې ښکلې او مېوه یې خوندوره ښکاره شوه، فکر یې وکړ چې دا ونه به د پوهې د حاصلولو دپاره څومره ښه وي. نو هغه مېوه یې راواخیستله او ویې خوړله او خپل مېړه ته یې چې د هغې سره ؤ، هم ورکړه او هغه هم وخوړله.', 'شجې ونې ته په جیر وکتل او هغه ونه د هغې په نظر کې شکلې او مېوه یې خوندوره شکاره شوه، فکر یې وکر چې دا ونه به د پوهې د حاصلولو دپاره چومره شه وی. نو هغه مېوه یې راواخیستله او ویې خورله او خپل مېره ته یې چې د هغې سره و، هم ورکره او هغه هم وخورله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43591, 'Genesis 3:7', 'Genesis', 3, 7, 'په هماغه وخت کې د هغوی سترګې وغړېدلې او پوه شول چې لوڅ دي، نو د انځر پاڼې یې یو تر بله سره وګنډلې او ځانونه یې ورباندې پټ کړل.', 'په هماغه وخت کې د هغوی سترګې وغرېدلې او پوه شول چې لوچ دی، نو د انجر پانې یې یو تر بله سره وګندلې او جانونه یې ورباندې پت کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
