(43607, 'Genesis 3:23', 'Genesis', 3, 23, 'نو څښتن خدای دوی د عدن د باغ څخه وشړل چې لاړ شي او په هغې ځمکې باندې کار وکړي چې د هغې د خاورې څخه آدم جوړ شوی ؤ.', 'نو چشتن خدای دوی د عدن د باغ چخه وشرل چې لار شی او په هغې جمکې باندې کار وکری چې د هغې د خاورې چخه ادم جور شوی و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43608, 'Genesis 3:24', 'Genesis', 3, 24, 'آدم یې وشاړه او د عدن د باغ لمرخاته خواته د ننوتلو په دروازه کې یې اسماني مخلوقات او هغه اور لرونکې توره چې هرې خواته به تاوېدله، ودرول، ترڅو څوک ونه شي کولای چې د ژوندانه ونې ته ورنژدې شي.', 'ادم یې وشاره او د عدن د باغ لمرخاته خواته د ننوتلو په دروازه کې یې اسمانی مخلوقات او هغه اور لرونکې توره چې هرې خواته به تاوېدله، ودرول، ترچو چوک ونه شی کولای چې د ژوندانه ونې ته ورنژدې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_3_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43609, 'Job 16:1', 'Job', 16, 1, 'بيا ايُوب جواب ورکړو،', 'بیا ایوب جواب ورکرو،', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43610, 'Job 16:2', 'Job', 16, 2, '”زۀ د دې څيزونو نه پخوا خبر يم، او ستاسو خبرې ما له تسلى نۀ راکوى.', '”زۀ د دې چیزونو نه پخوا خبر یم، او ستاسو خبرې ما له تسلی نۀ راکوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43611, 'Job 16:3', 'Job', 16, 3, 'ستاسو د هوائى خبرو څۀ حد نشته څۀ؟ يا په څۀ وجه باندې تاسو خبرې نۀ بندوئ؟', 'ستاسو د هوایی خبرو چۀ حد نشته چۀ؟ یا په چۀ وجه باندې تاسو خبرې نۀ بندوی؟', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43612, 'Job 16:4', 'Job', 16, 4, 'کۀ تاسو زما په ځائ وئ نو هم ما ستاسو خِلاف لوئې لوئې خبرې جوړولے شوې، او ستاسو سپکاوے به مې کړے وے.', 'کۀ تاسو زما په جای وی نو هم ما ستاسو خلاف لویې لویې خبرې جورولے شوې، او ستاسو سپکاوے به مې کرے وے.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43613, 'Job 16:5', 'Job', 16, 5, 'خو کۀ دا زۀ وے، نو ما به ستاسو حوصله افزائى کړے وے. او ما به دا کوشش کړے وے چې ستاسو غم لرې کړم.', 'خو کۀ دا زۀ وے، نو ما به ستاسو حوصله افزایی کرے وے. او ما به دا کوشش کرے وے چې ستاسو غم لرې کرم.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43614, 'Job 16:6', 'Job', 16, 6, 'خو کۀ زۀ د خپل ځان صفائى پېش کوم نو زۀ به په تکليف کښې کېږم، خو کۀ زۀ خبرې نۀ کوم نو ما ته بيا هم ډېر تکليف رارسيږى.', 'خو کۀ زۀ د خپل جان صفایی پېش کوم نو زۀ به په تکلیف کشې کېزم، خو کۀ زۀ خبرې نۀ کوم نو ما ته بیا هم دېر تکلیف رارسیزی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43615, 'Job 16:7', 'Job', 16, 7, 'اے خُدايه پاکه، زۀ اوس تا ډېر ستومانه کړے يم، تا زما مکمل خاندان تباه کړے دے.', 'اے خدایه پاکه، زۀ اوس تا دېر ستومانه کرے یم، تا زما مکمل خاندان تباه کرے دے.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43616, 'Job 16:8', 'Job', 16, 8, 'تا زۀ ګېر کړے يم، او دا زما خِلاف يو ثبوت دے، چې زۀ اوچ کلک او کمزورے شوے يم، او دا زما خِلاف ګواهى ورکوى.', 'تا زۀ ګېر کرے یم، او دا زما خلاف یو ثبوت دے، چې زۀ اوچ کلک او کمزورے شوے یم، او دا زما خلاف ګواهی ورکوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43617, 'Job 16:9', 'Job', 16, 9, 'هغۀ د خپلې غصې په وجه زۀ خراب کړے يم او زما نه نفرت کوى، هغۀ ما ته خپل غاښونه چيچلى دى، زما دشمن د هغۀ سترګې زما خِلاف برندوى.', 'هغۀ د خپلې غصې په وجه زۀ خراب کرے یم او زما نه نفرت کوی، هغۀ ما ته خپل غاشونه چیچلی دی، زما دشمن د هغۀ سترګې زما خلاف برندوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43618, 'Job 16:10', 'Job', 16, 10, 'خلق ما پورې خندا کوى، هغوئ په مسخرو کښې ما په مخ باندې وهى او زما خِلاف يې اتفاق کړے دے.', 'خلق ما پورې خندا کوی، هغوی په مسخرو کشې ما په مخ باندې وهی او زما خلاف یې اتفاق کرے دے.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43619, 'Job 16:11', 'Job', 16, 11, 'خُدائ پاک ما د خُدائ نه منکرو خلقو له ورکوى، او د بدعمله خلقو لاسونو ته مې حواله کوى.', 'خدای پاک ما د خدای نه منکرو خلقو له ورکوی، او د بدعمله خلقو لاسونو ته مې حواله کوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43620, 'Job 16:12', 'Job', 16, 12, 'زۀ صحيح سلامت وم او هغۀ زۀ دوه ټوټې کړم، هغۀ زۀ د څټ نه ونيولم او ټوټې ټوټې يې کړم، هغۀ زۀ د خپلې نښې په توګه ودرولم.', 'زۀ صحیح سلامت وم او هغۀ زۀ دوه توتې کرم، هغۀ زۀ د چت نه ونیولم او توتې توتې یې کرم، هغۀ زۀ د خپلې نشې په توګه ودرولم.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43621, 'Job 16:13', 'Job', 16, 13, 'د هغۀ غشى ويشتونکى زما نه تاو شول. هغۀ زما ګردې راوويستلې او په ما يې هيڅ رحم ونۀ کړو، هغۀ زما تريخے په زمکه بهر وغورزولو.', 'د هغۀ غشی ویشتونکی زما نه تاو شول. هغۀ زما ګردې راوویستلې او په ما یې هیچ رحم ونۀ کرو، هغۀ زما تریخے په زمکه بهر وغورزولو.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43622, 'Job 16:14', 'Job', 16, 14, 'هغۀ زۀ بيا مات رامات کړم، هغۀ د يو جنګيالى په شان په ما باندې رامنډه کړه.', 'هغۀ زۀ بیا مات رامات کرم، هغۀ د یو جنګیالی په شان په ما باندې رامنده کره.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43623, 'Job 16:15', 'Job', 16, 15, 'ما د ځان دپاره د ټاټ جامې ګنډلې دى، او هغۀ زۀ د خاورې په شان مېده کړے يم.', 'ما د جان دپاره د تات جامې ګندلې دی، او هغۀ زۀ د خاورې په شان مېده کرے یم.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43624, 'Job 16:16', 'Job', 16, 16, 'زما سترګې د ژړا نه سرې دى، او زما د سترګو ليمۀ تور شول.', 'زما سترګې د ژرا نه سرې دی، او زما د سترګو لیمۀ تور شول.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43625, 'Job 16:17', 'Job', 16, 17, 'اګر چې ما هيڅ ظلم زياتے نۀ دے کړے، او زما په دُعا کښې خلوص دے.', 'اګر چې ما هیچ ظلم زیاتے نۀ دے کرے، او زما په دعا کشې خلوص دے.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43626, 'Job 16:18', 'Job', 16, 18, 'اے زمکې، زما وينه مۀ پټوه، او زما د اِنصاف فرياد دې څوک نۀ ختموى.', 'اے زمکې، زما وینه مۀ پتوه، او زما د انصاف فریاد دې چوک نۀ ختموی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43627, 'Job 16:19', 'Job', 16, 19, 'خو بيا هم په آسمان کښې داسې ذات شته چې هغه زما مل دے او هغه به بې‌شکه ووائى چې زۀ په حقه يم.', 'خو بیا هم په اسمان کشې داسې ذات شته چې هغه زما مل دے او هغه به بې‌شکه ووایی چې زۀ په حقه یم.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43628, 'Job 16:20', 'Job', 16, 20, 'زما مينځګړے زما دوست دے او زما سترګې خُدائ پاک ته اوښکې تويوى.', 'زما مینجګرے زما دوست دے او زما سترګې خدای پاک ته اوشکې تویوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43629, 'Job 16:21', 'Job', 16, 21, 'او زما دوست زما دپاره خُدائ پاک سره بحث کوى لکه څنګه چې يو سړے د خپل دوست دپاره مِنت زارى کوى.', 'او زما دوست زما دپاره خدای پاک سره بحث کوی لکه چنګه چې یو سرے د خپل دوست دپاره منت زاری کوی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43630, 'Job 16:22', 'Job', 16, 22, 'صِرف يو څو کاله به پاتې وى چې زۀ به په هغه سفر باندې روان شم چې د هغې نه واپس کېدل نشته.', 'صرف یو چو کاله به پاتې وی چې زۀ به په هغه سفر باندې روان شم چې د هغې نه واپس کېدل نشته.', 'OT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43631, 'Esther 2:1', 'Esther', 2, 1, 'څه موده وروسته چې کله د خشایار پاچا قهر سوړ شو، هغه د وشتي، د هغه څه په اړه چې هغې کړي وو او د هغه فرمان په اړه چې د هغې په هکله یې ورکړی ؤ، فکر کاوه.', 'چه موده وروسته چې کله د خشایار پاچا قهر سور شو، هغه د وشتی، د هغه چه په اره چې هغې کری وو او د هغه فرمان په اره چې د هغې په هکله یې ورکری و، فکر کاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_2_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43632, 'Esther 2:2', 'Esther', 2, 2, 'نو د پاچا ځینو خدمتګارانو چې هغه ته نژدې خلک وو، وړاندیز وکړ: «د پاچا دپاره دې ښکلې پېغلې ولټول شي.', 'نو د پاچا جینو خدمتګارانو چې هغه ته نژدې خلک وو، وراندیز وکر: «د پاچا دپاره دې شکلې پېغلې ولتول شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_2_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43633, 'Esther 2:3', 'Esther', 2, 3, 'پاچا دې د خپلې امپراتورۍ په هر ولایت کې مامورین وټاکي چې ټولې ښکلې پېغلې دې حرمسرای ته چې د شوش په بالاحصار کې دی، راولي. هغوی دې د هیجای تر څارنې لاندې وي چې د پاچا خصي شوی خدمتګار دی او د حرمسرای مسوول دی. هغوی ته دې د اړتیا وړ د سینګار شیان تیار کړي.', 'پاچا دې د خپلې امپراتوری په هر ولایت کې مامورین وتاکی چې تولې شکلې پېغلې دې حرمسرای ته چې د شوش په بالاحصار کې دی، راولی. هغوی دې د هیجای تر چارنې لاندې وی چې د پاچا خصی شوی خدمتګار دی او د حرمسرای مسوول دی. هغوی ته دې د ارتیا ور د سینګار شیان تیار کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_2_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43634, 'Esther 2:4', 'Esther', 2, 4, 'نو بیا هغه پېغله چې د پاچا خوښه شوه د وشتي په ځای دې ملکه شي.» دا مشوره د پاچا خوښه شوه او هماغسې یې وکړل.', 'نو بیا هغه پېغله چې د پاچا خوشه شوه د وشتی په جای دې ملکه شی.» دا مشوره د پاچا خوشه شوه او هماغسې یې وکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Esther_2_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
